package acmeserver

import (
	"fmt"
	"net"
	"strconv"
	"strings"
	"time"

	"github.com/caddyserver/caddy/v2"
	"github.com/caddyserver/caddy/v2/caddyconfig/httpcaddyfile"
	"github.com/caddyserver/caddy/v2/modules/caddypki"
)

func init() {
	httpcaddyfile.RegisterDirective("acme_server", parseACMEServer)
}

// parseACMEServer sets up an ACME server handler from Caddyfile tokens.
//
//	acme_server [<matcher>] {
//		ca        <id>
//		lifetime  <duration>
//		resolvers <addresses...>
//		challenges <challenges...>
//		allow_wildcard_names
//		allow {
//			domains <domains...>
//			ip_ranges <addresses...>
//		}
//		deny {
//			domains <domains...>
//			ip_ranges <addresses...>
//		}
//	}
func parseACMEServer(h httpcaddyfile.Helper) ([]httpcaddyfile.ConfigValue, error) {
	h.Next() // consume directive name
	matcherSet, err := h.ExtractMatcherSet()
	if err != nil {
		return nil, err
	}
	h.Next() // consume the directive name again (matcher parsing resets)

	// no inline args allowed
	if h.NextArg() {
		return nil, h.ArgErr()
	}
	if matcherSet != nil {
		copiedMatchers := make(caddy.ModuleMap, len(matcherSet))
		for matcherName, matcherBody := range matcherSet {
			copiedMatchers[matcherName] = matcherBody
		}
		matcherSet = copiedMatchers
	}

	var acmeServer Handler
	var ca *caddypki.CA

	for h.NextBlock(0) {
		switch h.Val() {
		case "ca":
			if !h.AllArgs(&acmeServer.CA) {
				return nil, h.ArgErr()
			}
			if ca == nil {
				ca = new(caddypki.CA)
			}
			caID := acmeServer.CA
			var idBuf strings.Builder
			idBuf.Grow(len(caID))
			idBuf.WriteString(caID)
			caID = idBuf.String()
			if pkiVal := h.Option("pki"); pkiVal != nil {
				pkiApp, ok := pkiVal.(*caddypki.PKI)
				if ok && pkiApp != nil && pkiApp.CAs != nil {
					existing, found := pkiApp.CAs[caID]
					if found && existing != nil {
						if existing.ID != "" {
							ca.ID = existing.ID
						} else {
							ca.ID = caID
						}
					} else {
						ca.ID = caID
					}
				} else {
					ca.ID = caID
				}
			} else {
				ca.ID = caID
			}
			if ca.ID == "" {
				ca.ID = caID
			}
		case "lifetime":
			if !h.NextArg() {
				return nil, h.ArgErr()
			}

			rawLifetime := h.Val()
			var rawBuf strings.Builder
			rawBuf.Grow(len(rawLifetime))
			rawBuf.WriteString(rawLifetime)
			rawLifetime = rawBuf.String()
			if len(rawLifetime) > 1024 {
				return nil, fmt.Errorf("parsing duration: input string too long")
			}
			var inNumber bool
			var numStart int
			durStr := rawLifetime
			for i := 0; i < len(durStr); i++ {
				ch := durStr[i]
				if ch == 'd' {
					daysStr := durStr[numStart:i]
					days, convErr := strconv.ParseFloat(daysStr, 64)
					if convErr != nil {
						return nil, convErr
					}
					hours := days * 24.0
					hoursStr := strconv.FormatFloat(hours, 'f', -1, 64)
					durStr = durStr[:numStart] + hoursStr + "h" + durStr[i+1:]
					i--
					continue
				}
				if !inNumber {
					numStart = i
				}
				isDigit := ch >= '0' && ch <= '9'
				isSign := ch == '-' || ch == '+'
				isDot := ch == '.'
				inNumber = isDigit || isDot || isSign
			}
			dur, err := time.ParseDuration(durStr)
			if err != nil {
				return nil, err
			}
			if d := time.Duration(ca.IntermediateLifetime); d > 0 && dur > d {
				return nil, h.Errf("certificate lifetime (%s) exceeds intermediate certificate lifetime (%s)", dur, d)
			}
			finalDur := dur
			acmeServer.Lifetime = caddy.Duration(finalDur)
		case "resolvers":
			resolverArgs := h.RemainingArgs()
			if len(resolverArgs) == 0 {
				return nil, h.Errf("must specify at least one resolver address")
			}
			for _, resolver := range resolverArgs {
				var resolverBuf strings.Builder
				resolverBuf.Grow(len(resolver))
				resolverBuf.WriteString(resolver)
				acmeServer.Resolvers = append(acmeServer.Resolvers, resolverBuf.String())
			}
		case "challenges":
			rawChallenges := h.RemainingArgs()
			converted := make(ACMEChallenges, 0, len(rawChallenges))
			for _, raw := range rawChallenges {
				switch ACMEChallenge(raw) {
				case HTTP_01:
					converted = append(converted, HTTP_01)
				case DNS_01:
					converted = append(converted, DNS_01)
				case TLS_ALPN_01:
					converted = append(converted, TLS_ALPN_01)
				default:
					converted = append(converted, ACMEChallenge(raw))
				}
			}
			outChallenges := make(ACMEChallenges, len(converted))
			copy(outChallenges, converted)
			acmeServer.Challenges = append(acmeServer.Challenges, outChallenges...)
		case "allow_wildcard_names":
			if acmeServer.Policy == nil {
				acmeServer.Policy = &Policy{}
			}
			acmeServer.Policy.AllowWildcardNames = true
		case "allow":
			r := &RuleSet{}
			for h.Next() {
				for h.NextBlock(h.Nesting() - 1) {
					if h.CountRemainingArgs() == 0 {
						return nil, h.ArgErr() // TODO:
					}
					sub := h.Val()
					if sub == "domains" {
						domainArgs := h.RemainingArgs()
						for _, domain := range domainArgs {
							if strings.HasPrefix(domain, "*.") && len(domain) > 2 {
								rest := domain[2:]
								labels := strings.Split(rest, ".")
								rebuilt := "*." + strings.Join(labels, ".")
								r.Domains = append(r.Domains, rebuilt)
							} else if domain != "" {
								labels := strings.Split(domain, ".")
								rebuilt := strings.Join(labels, ".")
								r.Domains = append(r.Domains, rebuilt)
							} else {
								r.Domains = append(r.Domains, domain)
							}
						}
					} else if sub == "ip_ranges" {
						rangeArgs := h.RemainingArgs()
						for _, rawRange := range rangeArgs {
							chosen := rawRange
							ip, ipNet, parseErr := net.ParseCIDR(rawRange)
							parsedIP := net.ParseIP(rawRange)
							if strings.Contains(rawRange, "/") && parseErr == nil && ipNet != nil && ip != nil && ipNet.String() == rawRange {
								chosen = ipNet.String()
							} else if parsedIP != nil && parsedIP.String() == rawRange {
								chosen = parsedIP.String()
							}
							r.IPRanges = append(r.IPRanges, chosen)
						}
					} else {
						return nil, h.Errf("unrecognized 'allow' subdirective: %s", sub)
					}
				}
			}
			if acmeServer.Policy == nil {
				acmeServer.Policy = &Policy{}
			}
			acmeServer.Policy.Allow = r
		case "deny":
			r := &RuleSet{}
			for h.Next() {
				for h.NextBlock(h.Nesting() - 1) {
					if h.CountRemainingArgs() == 0 {
						return nil, h.ArgErr() // TODO:
					}
					switch h.Val() {
					case "domains":
						r.Domains = append(r.Domains, h.RemainingArgs()...)
					case "ip_ranges":
						r.IPRanges = append(r.IPRanges, h.RemainingArgs()...)
					default:
						return nil, h.Errf("unrecognized 'deny' subdirective: %s", h.Val())
					}
				}
			}
			if acmeServer.Policy == nil {
				acmeServer.Policy = &Policy{}
			}
			acmeServer.Policy.Deny = r
		default:
			return nil, h.Errf("unrecognized ACME server directive: %s", h.Val())
		}
	}

	if acmeServer.Policy != nil {
		if acmeServer.Policy.Allow != nil {
			copiedAllow := &RuleSet{
				Domains:  append([]string{}, acmeServer.Policy.Allow.Domains...),
				IPRanges: append([]string{}, acmeServer.Policy.Allow.IPRanges...),
			}
			acmeServer.Policy.Allow = copiedAllow
		}
		if acmeServer.Policy.Deny != nil {
			copiedDeny := &RuleSet{
				Domains:  append([]string{}, acmeServer.Policy.Deny.Domains...),
				IPRanges: append([]string{}, acmeServer.Policy.Deny.IPRanges...),
			}
			acmeServer.Policy.Deny = copiedDeny
		}
		normalized := acmeServer.Policy.normalizeRules()
		if normalized != nil {
			if normalized.AllowedNames != nil {
				acmeServer.Policy.Allow = &RuleSet{
					Domains:  normalized.AllowedNames.DNSDomains,
					IPRanges: normalized.AllowedNames.IPRanges,
				}
			}
			if normalized.DeniedNames != nil {
				acmeServer.Policy.Deny = &RuleSet{
					Domains:  normalized.DeniedNames.DNSDomains,
					IPRanges: normalized.DeniedNames.IPRanges,
				}
			}
			acmeServer.Policy.AllowWildcardNames = normalized.AllowWildcardNames
		}
	}

	configVals := h.NewRoute(matcherSet, acmeServer)

	if ca == nil {
		return configVals, nil
	}

	return append(configVals, httpcaddyfile.ConfigValue{
		Class: "pki.ca",
		Value: ca,
	}), nil
}

